import time

n = 1_000_000
data = list(range(n))
target = n - 1

def linear_search(nums, x):
    for i, v in enumerate(nums):
        if v == x:
            return i, i + 1
    return -1, len(nums)

def binary_search(nums, x):
    lo, hi, cnt = 0, len(nums) - 1, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        cnt += 1
        if nums[mid] == x:
            return mid, cnt
        if nums[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1, cnt

t0 = time.perf_counter()
pos1, c1 = linear_search(data, target)
t1 = time.perf_counter()
pos2, c2 = binary_search(data, target)
t2 = time.perf_counter()

print(f'数据量 n = {n}，要找的是 {target}')
print(f'逐个查找：比较 {c1} 次，耗时 {(t1 - t0) * 1000:.1f} 毫秒')
print(f'二分查找：比较 {c2} 次，耗时 {(t2 - t1) * 1000:.3f} 毫秒')
print(f'比较次数相差 {c1 // c2} 倍')

