def count_log(n):
    ops, size = 0, n
    while size > 1:
        size = (size + 1) // 2
        ops += 1
    return ops

def count_linear(n):
    ops = 0
    for _ in range(n):
        ops += 1
    return ops

def count_quadratic(n):
    ops = 0
    for _ in range(n):
        for _ in range(n):
            ops += 1
    return ops

print('      n   O(log n)     O(n)   O(n log n)        O(n^2)')
for n in (10, 100, 1000):
    lg = count_log(n)
    lin = count_linear(n)
    quad = count_quadratic(n)
    print(f'{n:>7} {lg:>10} {lin:>9} {lin * lg:>12} {quad:>13}')

print('n 从 1000 涨到 1000000 时，log n 只从 10 涨到 20，n^2 从 10^6 涨到 10^12')

quiz.solution:
import math

def growth(n):
    return n, n * n, math.ceil(math.log2(n))

for n in (10, 100, 1000):
    lin, quad, lg = growth(n)
    print(f'n={n}: O(n)={lin}, O(n^2)={quad}, O(log n)={lg}')
